<?php require '../config/database.php';auth();$rows=$pdo->query('SELECT s.*,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id ORDER BY s.id DESC')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>المبيعات</h1><a class="btn" href="add.php">عملية بيع</a><table><tr><th>#</th><th>العميل</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>طريقة الدفع</th><th>التاريخ</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=htmlspecialchars($r['customer']??'نقدي')?></td><td><?=$r['total']?></td><td><?=$r['paid']?></td><td><?=$r['remaining']?></td><td><?=$r['payment_method']?></td><td><?=$r['created_at']?></td></tr><?php endforeach;?></table></main>
